    @Test
    fun testIsoSc17Wg10BangkokRical() = runTest {
        val signedRical = SignedRical.parse(
            encodedSignedRical = RICAL_BASE64_ISO_SC17WG10_TEST_EVENT_BANGKOK_TH_AUG_2026.fromBase64(),
            disableSignatureVerification = !Crypto.supportedCurves.contains(EcCurve.BRAINPOOLP256R1)
        )

        val certChain = signedRical.ricalProviderCertificateChain
        assertEquals(1, certChain.certificates.size)
        val signerCert = certChain.certificates.first()
        assertEquals(
            "OU=Certificate Authority,O=Bangkok 2026,C=TH,CN=RICAL Signer Certificate",
            signerCert.subject.name
        )

        val r = signedRical.rical
        assertEquals("Bangkok 2026", r.provider)
        assertEquals("1.0", r.version)
        assertEquals(Rical.RICAL_TYPE_READER_AUTHENTICATION, r.type)
        assertEquals("2026-08-14T10:52:12Z", r.date.toString())
        assertEquals("2027-02-14T10:52:12Z", r.nextUpdate.toString())
        assertEquals("2027-02-14T10:52:12Z", r.notAfter.toString())
        assertEquals(3L, r.id)
        assertEquals("https://bangkok2026.mdoc.online/TrustedLists/Rical.rical", r.latestRicalUrl)
        assertEquals(14, r.certificateInfos.size)

        // Inspect the first certificate (Credence ID)
        val ci0 = r.certificateInfos.first()
        assertEquals(
            "CN=CredenceID Reader Root CA,O=CredenceID,ST=California,C=US",
            ci0.certificate.subject.name
        )
        assertEquals("Credence ID Reader Root CA", ci0.name)
        assertEquals("US", ci0.issuingCountry)
        assertEquals("California", ci0.stateOrProvinceName)
        assertEquals(true, ci0.isTrustAnchor)

        // Inspect cert 11 (verifier.multipaz.org) which has negative bignum (Tag 3) serial number
        val ci11 = r.certificateInfos[11]
        assertEquals(
            "CN=verifier.multipaz.org Reader CA,C=US",
            ci11.certificate.subject.name
        )
        assertEquals("verifier.multipaz.org Reader Root", ci11.name)
        assertEquals("US", ci11.issuingCountry)
        assertEquals(true, ci11.isTrustAnchor)
    }

